import { Switch } from '@absoluteui/components/switch';

const host = document.createElement('div');
document.body.append(host);
const notifications = Switch.create(host, { label: 'Email notifications', description: 'Weekly summary of activity' });
host.addEventListener('aui-change', () => {
  document.documentElement.dataset.notifications = String(notifications.checked);
});

import { Switch } from '@absoluteui/components/switch';

const host = document.createElement('div');
document.body.append(host);
const sync = Switch.create(host, { label: 'Sync across devices', checked: true });

async function save(on: boolean): Promise<void> {
  const response = await fetch('/api/settings/sync', { method: 'PUT', body: JSON.stringify({ on }) });
  if (!response.ok) {
    sync.setChecked(!on);
    sync.setCustomError('Could not save. Try again.');
    sync.reportValidity();
  }
}

host.addEventListener('aui-change', () => {
  void save(sync.checked);
});
